    }

    if (forestVolume > 0.001 && forestUrl) {
      if (!forestActive) {
        startLoopFn(forestUrl, { bus: AMBIENT_LOOP_BUS, volume: forestVolume, fadeIn: 0.4 });
        forestActive = true;
      } else {
