function radialGain(dist, radius, peak) {
  if (!Number.isFinite(dist)) return 0;
  if (dist <= 1) return peak;
  if (dist >= radius) return 0;
  const t = (dist - 1) / (radius - 1);
  return peak * Math.pow(1 - t, 1.25);
