// src/rules/systems/aiFarmAnimalSystem.js
// Simple wandering AI for passive farm animals on the overworld (depth 0).
// Animals randomly scurry with a high rest chance, staying near their spawn.

import { Faction } from "../components/Faction.js";
import { CreatureType, CREATURE_TYPES } from "../components/CreatureType.js";
import { MoveIntent } from "../components/Intents/MoveIntent.js";
import { DungeonState } from "../components/DungeonState.js";
import { NamedIdentity } from "../components/NamedIdentity.js";
import { canActThisTurn } from "../utils/speedGate.js";
import { CARDINAL_DIRS } from "../utils/directions.js";
import { isWalkable } from "../environment/dungeon/tileMap.js";
import { playerEntity } from "../utils/queries.js";
import { forEachInRadius } from "../utils/spatialIndex.js";

const ACTIVE_RADIUS = 8;
const VOCALIZATION_COOLDOWN = 200; // turns between vocalizations per chicken

/** Track vocalization cooldown per entity (Map<id, turnsLeft>) */
const _vocalizationCooldowns = new Map();

/** @param {import('../../lib/ecs-js/index.js').World} world */
export function aiFarmAnimalSystem(world) {
  // Only run on the overworld.
  let depth = -1;
  for (const [, ds] of world.query(DungeonState)) {
    depth = ds.currentDepth ?? -1;
    break;
  }
  if (depth !== 0) return;

  const player = playerEntity(world);
  if (!player) return;
  const pp = player.pos;

  forEachInRadius(world, pp.x, pp.y, ACTIVE_RADIUS, (id, pos) => {
    const fac = world.get(id, Faction);
    if (!fac || fac.key !== "neutral") return;

    const ct = world.get(id, CreatureType);
    if (!ct || ct.type !== CREATURE_TYPES.beast) return;

    if (!canActThisTurn(world, id)) return;
    if (world.has(id, MoveIntent)) return;

    // Decrement vocalization cooldown
    const cooldown = _vocalizationCooldowns.get(id) ?? 0;
    if (cooldown > 0) {
      _vocalizationCooldowns.set(id, cooldown - 1);
    }

    // 5% chance to vocalize (if not on cooldown) — chickens cluck/cheep occasionally
    if (cooldown === 0 && world.rand() < 0.05) {
      const identity = world.get(id, NamedIdentity)?.identity;
      if (identity) {
        world.emit?.('creature:vocalize', {
          id,
          identity,
          at: { x: pos.x | 0, y: pos.y | 0 },
        });
        _vocalizationCooldowns.set(id, VOCALIZATION_COOLDOWN);
      }
    }

    // 70% chance to rest — chickens mostly peck in place.
    if (world.rand() < 0.7) return;

    const dir = CARDINAL_DIRS[Math.floor(world.rand() * CARDINAL_DIRS.length)];
    const nx = (pos.x | 0) + dir.dx;
    const ny = (pos.y | 0) + dir.dy;
    if (!isWalkable(nx, ny)) return;

    try { world.add(id, MoveIntent, { dx: dir.dx, dy: dir.dy }); } catch {}
  });
}
import { AGGRO_LEVELS, AggroState } from "../components/AggroState.js";
import { NamedIdentity } from "../components/NamedIdentity.js";
import { Pet } from "../components/Pet.js";
import { Vitality } from "../components/Vitality.js";
import { getMonster } from "../data/monsters.js";
import {
  resolveSleepProfile,
  resolveSleepScheduleNow,
} from "../data/sleepProfiles.js";
import { isAsleep, putActorToSleep, tryWakeActor } from "../utils/sleep.js";

function isControlledCreature(world, id) {
  return world.has(id, Pet);
}

function isSafeToFallAsleep(world, id) {
  const aggro = world.get(id, AggroState);
  if (!aggro) return true;
  return aggro.alertLevel === AGGRO_LEVELS.unaware;
}

/**
 * Applies time-of-day sleep schedules from monster sleep profiles.
 *
 * Scheduled sleep never overrides active aggro: an awake monster in any
 * non-unaware aggro state stays awake, even if the rest phase starts.
 *
 * @param {import("../../lib/ecs-js/index.js").World} world
 */
export function sleepScheduleSystem(world) {
  for (const [id, ident, vit] of world.query(NamedIdentity, Vitality)) {
    if (vit.hp <= 0) continue;
    if (isControlledCreature(world, id)) continue;

    const def = getMonster(String(ident.identity || ""));
    if (!def?.sleep) continue;

    const shouldSleep = resolveSleepScheduleNow(def.sleep, world.step || 0);
    if (shouldSleep == null) continue;

    if (!shouldSleep) {
      if (isAsleep(world, id)) {
        tryWakeActor(world, id, { reason: "scheduled_wake", intensity: 999 });
      }
      continue;
    }

    if (isAsleep(world, id)) continue;
    if (!isSafeToFallAsleep(world, id)) continue;

    const resolved = resolveSleepProfile(def.sleep);
    if (!resolved) continue;
    putActorToSleep(world, id, {
      reason: "scheduled_rest",
      wakeDifficulty: resolved.wakeDifficulty,
      wakeRadius: resolved.wakeRadius,
      wakeOnDamage: resolved.wakeOnDamage,
    });
  }
}
import { getTownPhase } from "./calendar.js";

const SLEEP_PROFILES = Object.freeze({
  roosting: Object.freeze({
    wakeDifficulty: 5,
    wakeRadius: 2,
    wakeOnDamage: true,
  }),
  nocturnal_roost: Object.freeze({
    wakeDifficulty: 5,
    wakeRadius: 2,
    wakeOnDamage: true,
  }),
  dormant: Object.freeze({
    wakeDifficulty: 4,
    wakeRadius: 1,
    wakeOnDamage: true,
  }),
  ancient: Object.freeze({
    wakeDifficulty: 14,
    wakeRadius: 3,
    wakeOnDamage: true,
  }),
  diurnal: Object.freeze({
    wakeDifficulty: 7,
    wakeRadius: 2,
    wakeOnDamage: true,
    restPhases: Object.freeze(["home", "sleep"]),
  }),
  nocturnal: Object.freeze({
    wakeDifficulty: 7,
    wakeRadius: 2,
    wakeOnDamage: true,
    restPhases: Object.freeze(["breakfast", "work", "pub"]),
  }),
  crepuscular: Object.freeze({
    wakeDifficulty: 7,
    wakeRadius: 2,
    wakeOnDamage: true,
    restPhases: Object.freeze(["sleep", "work"]),
  }),
  cathemeral: Object.freeze({
    wakeDifficulty: 6,
    wakeRadius: 2,
    wakeOnDamage: true,
  }),
});

const SLEEP_CONTEXT_OVERRIDES = Object.freeze({
  diurnal_den: Object.freeze({
    wakeDifficulty: 8,
    wakeRadius: 2,
    wakeOnDamage: true,
    restPhases: Object.freeze(["home", "sleep"]),
  }),
});

function normalizeSleepChance(value, fallback = 1) {
  if (!Number.isFinite(value)) return fallback;
  return Math.max(0, Math.min(1, Number(value)));
}

/**
 * Resolve high-level sleep authoring into SleepState construction data.
 *
 * Authoring accepts:
 *   sleep: "roosting"
 *   sleep: { pattern: "roosting", chance: 0.45 }
 *   sleep: { pattern: "nocturnal", context: "roost", chance: 0.45 }
 *
 * @param {string|{pattern?:string,context?:string,chance?:number}|null|undefined|false} sleep
 * @returns {{ chance:number, wakeDifficulty:number, wakeRadius:number, wakeOnDamage:boolean, restPhases:string[]|null }|null}
 */
export function resolveSleepProfile(sleep) {
  if (!sleep) return null;

  const pattern = typeof sleep === "string"
    ? sleep
    : String(sleep.pattern || "").trim();
  const context = typeof sleep === "object" ? String(sleep.context || "").trim() : "";
  const profileId = context ? `${pattern}_${context}` : pattern;
  const base = SLEEP_CONTEXT_OVERRIDES[profileId] || SLEEP_PROFILES[profileId] || SLEEP_PROFILES[pattern];
  if (!base) return null;

  const chance = normalizeSleepChance(typeof sleep === "object" ? sleep.chance : undefined, 1);
  return {
    chance,
    wakeDifficulty: base.wakeDifficulty,
    wakeRadius: base.wakeRadius,
    wakeOnDamage: base.wakeOnDamage,
    restPhases: Array.isArray(base.restPhases) ? base.restPhases : null,
  };
}

export function listSleepProfileIds() {
  return [...Object.keys(SLEEP_PROFILES), ...Object.keys(SLEEP_CONTEXT_OVERRIDES)];
}

/**
 * @param {string|{pattern?:string,context?:string,chance?:number}|null|undefined|false} sleep
 * @param {number} step
 * @returns {boolean|null} true = should sleep now, false = should wake now, null = no time schedule
 */
export function resolveSleepScheduleNow(sleep, step) {
  const resolved = resolveSleepProfile(sleep);
  if (!resolved || !Array.isArray(resolved.restPhases)) return null;
  return resolved.restPhases.includes(getTownPhase(step));
}

